test('MCQ paper creation retries a cold Firebase transaction cache and never overwrites the bank',async()=>{const f=fixture();const saved=await f.service('mcq-principal',{operation:'mcq-contribute',requestId:'cold_deposit',subjectId:'english',topic:'Mixed',verified:true,questions:Array.from({length:10},(_,i)=>({stem:'Question '+i,options:['one','two','three','four'],answer:'B'}))},'principal');const base=f.db.ref;let attempts=0;const db={ref:path=>{const ref=base(path);if(path!=='cbse/mcq')return ref;return {...ref,transaction:async fn=>{attempts++;const initial=fn(null);assert.equal(initial,null);return ref.transaction(fn);}};}};const service=createStaffService({db,auth:f.auth,now:()=>1000000,displayKey:Buffer.alloc(32,7),viewSecret});const result=await service('mcq-principal',{operation:'mcq-paper',requestId:'cold_paper_request',questionIds:saved.questionIds},'principal');assert.equal(attempts,1);assert.equal(result.ok,true);assert.deepEqual(f.data.cbse.mcq.papers[result.paperId].questionIds,saved.questionIds);assert.equal(Object.keys(f.data.cbse.mcq.questions).length,10);const before=structuredClone(f.data.cbse.mcq);await assert.rejects(service('mcq-principal',{operation:'mcq-paper',requestId:'genuinely_missing',questionIds:[...saved.questionIds.slice(1),'M10-999999']},'principal'),/no longer exist/);assert.deepEqual(f.data.cbse.mcq,before);});
