test('answer keys require verified PIN or Principal, stay frozen, and never leak through normal reads',async()=>{const {service,data}=fixture();await service('set-pin',{staffId:'X:one',pin:'123'},'principal');const deposit=await service('mcq-principal',{operation:'mcq-contribute',classId:'X',subjectId:'english',topic:'Topic',single:true,verified:true,requestId:'answer_key_seed',questions:[{verbatim:true,stem:'Original question',answer:'B'}]},'principal'),paper=await service('mcq-principal',{operation:'mcq-paper',classId:'X',subjectId:'english',requestId:'answer_key_paper',questionIds:deposit.questionIds},'principal');const base={operation:'mcq-answer-key',classId:'X',subjectId:'english',paperId:paper.paperId,staffId:'X:one'};await assert.rejects(service('mcq-answer-key',base),/PIN/);await assert.rejects(service('pin-submit',{...base,pin:'000'}),/PIN does not match/);await assert.rejects(service('mcq-principal',base,'outsider'),/Principal/);data.cbse.mcq.questions[deposit.questionIds[0]].answer='D';const key=await service('pin-submit',{...base,pin:'123'});assert.equal(key.answerKey.questions[0].answer,'B');assert.equal(key.answerKey.questions[0].question.stem,'Original question');assert.equal((await service('mcq-principal',base,'principal')).answerKey.questions[0].answer,'B');const ordinary=await service('mcq-read',{classId:'X',paperId:paper.paperId,answerKey:true},'principal');assert.ok(!JSON.stringify(ordinary).includes('"answer"'));assert.equal(ordinary.answerKey,undefined);});

