test('Principal remedial create/edit/cancel uses the existing session without PIN and broadcasts revision/status',async()=>{const f=fixture(),input={teacherId:'X:one',scope:'X|a|english',studentKeys:['X:a:one'],purpose:'Principal test',schedule:'day',from:'2030-01-02',slot:'morning',requestId:'principal_remedial_test'};const made=await f.service('remedial-principal',input,'principal');assert.equal(f.data.cbse.mission.remedialPlans[made.planId].createdBy,'principal');await f.service('remedial-principal',{...input,operation:'edit',planId:made.planId,expectedRevision:0,requestId:'principal_edit_test',purpose:'Revised by Principal',keepDates:true},'principal');assert.equal(Object.keys(f.data.cbse.mission.remedialPlans).length,1);assert.equal(f.data.cbse.mission.remedialPlans[made.planId].revision,1);await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');await f.service('pin-submit',{...input,operation:'remedial-plan',planOperation:'edit',planId:made.planId,expectedRevision:1,requestId:'teacher_edit_program',purpose:'Teacher revision',staffId:'X:one',pin:'123',keepDates:true});assert.equal(f.data.cbse.mission.remedialPlans[made.planId].updatedBy,'X:one');await f.service('remedial-principal',{operation:'cancel',planId:made.planId,expectedRevision:2},'principal');const login=await f.service('view-login',{password:'synthetic-curtain'}),view=await f.service('view-data',{},'','plan-board',{viewerToken:login.viewerToken});assert.equal(view.mission.remedialPlans[made.planId].status,'cancelled');assert.equal(view.mission.remedialPlans[made.planId].cancelledByName,'Principal');assert.equal(f.data.cbse.public,undefined);});

