test('Chamber setup reuses all distributed Mission PINs, preserves disabled access and creates only missing staff/PINs',async()=>{const f=fixture();f.data.cbse.facultyDraft.classes.X.teachers.one.name='MR. ABHISHEK SINGH';f.data.cbse.mission.staff.disabled={name:'Synthetic Disabled PRT',designation:'PRT',kind:'prt',status:'active'};await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');await f.service('set-pin',{staffId:'support:disabled',pin:'456'},'principal');await f.service('disable',{staffId:'support:disabled'},'principal');const original=structuredClone(f.data.cbse.staffAccess);for(const action of ['roll-call-setup','roll-call-context'])await assert.rejects(f.service(action,{},'outsider'),/Principal/);const setup=await f.service('roll-call-setup',{},'principal');assert.equal(setup.createdStaff,45);assert.equal(setup.createdPins,45);assert.deepEqual(f.data.cbse.staffAccess['X:one'],original['X:one']);assert.deepEqual(f.data.cbse.staffAccess['support:disabled'],original['support:disabled']);const list=await f.service('list',{},'principal'),generated=Object.entries(list.access).filter(([id])=>!original[id]).map(([,a])=>a.pin);assert.equal(new Set(generated).size,45);assert.ok(!generated.includes('123')&&!generated.includes('456'));const again=await f.service('roll-call-setup',{},'principal');assert.equal(again.createdStaff,0);assert.equal(again.createdPins,0);assert.deepEqual(f.data.cbse.staffAccess['X:one'],original['X:one']);const context=await f.service('roll-call-context',{},'principal');assert.deepEqual(context.draft.classes.X.sections.a.students,{});assert.ok(context.faculty.classes.X.teachers.one);});
