test('reporting draft/publish is Principal-only and versioned server-side without changing old submissions',async()=>{const f=fixture(),{defaultReporting}=await import('../cbse-reporting-model.js');await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');const view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken},draft=defaultReporting();draft.title='Published Staff Reporting';draft.groups.morning=[{id:'new_duty',label:'New published duty?',type:'yesno',required:true}];await assert.rejects(f.service('chamber-principal',{operation:'read'},'outsider'),/Principal/);await f.service('chamber-principal',{operation:'reporting-save',expectedRevision:0,draft},'principal');let publicView=await f.service('chamber-read',{},'','test',session);assert.equal(publicView.reporting.title,'Roll Call');await f.service('chamber-principal',{operation:'reporting-publish',expectedRevision:1,draft},'principal');publicView=await f.service('roll-call-read',{},'','test',session);assert.equal(publicView.reporting.title,draft.title);const payload={operation:'roll-call',staffId:'X:one',pin:'123',rollOperation:'report',wing:'secondary',period:'morning',reported:'yes',answers:{new_duty:'yes'}};await assert.rejects(f.service('pin-submit',{...payload,formVersion:1},'','test',session),/form changed/);await f.service('pin-submit',{...payload,formVersion:2},'','test',session);const old=structuredClone(f.data.cbse.rollCall.reports);draft.groups.morning=[];await f.service('chamber-principal',{operation:'reporting-publish',expectedRevision:2,draft},'principal');assert.deepEqual(f.data.cbse.rollCall.reports,old);assert.equal(Object.values(old)[0].questionSnapshot[0].label,'New published duty?');});
test('podcast video IDs require assigned staff PINs; acknowledgements recheck assignment/version and preserve distributed PINs',async()=>{const f=fixture();f.data.cbse.facultyDraft.classes.X.teachers.two={name:'Other Teacher',designation:'TGT',subjects:'',teachingSections:'',status:'active'};for(const[id,pin]of [['X:one','123'],['X:two','456']])await f.service('set-pin',{staffId:id,pin},'principal');const pins=structuredClone(f.data.cbse.staffAccess),view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken};const published=await f.service('chamber-principal',{operation:'podcast-publish',expectedRevision:0,title:'Private teacher guidance',youtubeUrl:'https://youtu.be/abcdefghijk',recipientIds:['X:one']},'principal');const publicData=await f.service('chamber-read',{},'','test',session);assert.ok(!JSON.stringify(publicData).includes('abcdefghijk'));assert.equal(publicData.videos[0].title,'Private teacher guidance');assert.deepEqual(publicData.videos[0].recipients.map(p=>p.id),['X:one']);assert.ok(!JSON.stringify(publicData).includes('pinHash'));const one={operation:'podcast-list',staffId:'X:one',pin:'123'},two={operation:'podcast-list',staffId:'X:two',pin:'456'};await assert.rejects(f.service('pin-submit',one),/viewing password/);assert.equal((await f.service('pin-submit',one,'','test',session)).videos[0].youtubeId,'abcdefghijk');assert.deepEqual((await f.service('pin-submit',two,'','test',session)).videos,[]);await assert.rejects(f.service('pin-submit',{...two,operation:'podcast-ack',id:published.id,version:1,acknowledged:true},'','test',session),/not assigned/);await assert.rejects(f.service('pin-submit',{...one,operation:'podcast-ack',id:published.id,version:2,acknowledged:true},'','test',session),/updated/);await f.service('pin-submit',{...one,operation:'podcast-ack',id:published.id,version:1,acknowledged:true,remark:'Noted the instructions.'},'','test',session);const admin=await f.service('chamber-principal',{operation:'read'},'principal');assert.equal(admin.podcasts.acks[published.id][1]['X:one'].name,'Synthetic Teacher');assert.deepEqual(f.data.cbse.staffAccess,pins);});
test('published content and acknowledgement/approval transactions retry an initially empty Firebase cache',async()=>{const f=fixture(),{defaultReporting}=await import('../cbse-reporting-model.js');await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');const draft=defaultReporting();await f.service('chamber-principal',{operation:'reporting-save',expectedRevision:0,draft},'principal');const video=await f.service('chamber-principal',{operation:'podcast-publish',expectedRevision:0,title:'Cold cache test',youtubeUrl:'https://youtu.be/abcdefghijk',recipientIds:['X:one']},'principal');const view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken};await f.service('pin-submit',{operation:'roll-call',staffId:'X:one',pin:'123',rollOperation:'report',wing:'secondary',period:'morning',reported:'no',leaveType:'today',answers:{informed:'yes',cover:'yes',exam:'yes',data:'yes'},noReason:'Emergency leave required today.'},'','test',session);const base=f.db.ref,paths=new Set(['cbse/chamber/reporting','cbse/chamber/podcasts','cbse/rollCall']),db={ref:path=>{const ref=base(path);return paths.has(path)?{...ref,transaction:async fn=>{assert.equal(fn(null),null);return ref.transaction(fn);}}:ref;}},cold=createStaffService({db,auth:f.auth,now:()=>1000000,displayKey:Buffer.alloc(32,7),viewSecret});await cold('chamber-principal',{operation:'reporting-publish',expectedRevision:1,draft},'principal');await cold('pin-submit',{operation:'podcast-ack',staffId:'X:one',pin:'123',id:video.id,version:1,acknowledged:true},'','test',session);await cold('roll-call-principal',{rollOperation:'approve',reportId:Object.keys(f.data.cbse.rollCall.reports)[0]},'principal');assert.equal(Object.values(f.data.cbse.rollCall.reports)[0].status,'approved');assert.ok(f.data.cbse.chamber.podcasts.acks[video.id][1]['X:one']);});
test('Principal controls publication of pending podcast names; staff cannot publish and private acknowledgements remain private',async()=>{const f=fixture();await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');const view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken};const video=await f.service('chamber-principal',{operation:'podcast-publish',expectedRevision:0,title:'Pending guidance',youtubeUrl:'https://youtu.be/abcdefghijk',recipientIds:['X:one']},'principal');const command={operation:'podcast-pending-publish',id:video.id,expectedRevision:1};await assert.rejects(f.service('chamber-principal',command,'outsider'),/Principal/);await f.service('chamber-principal',command,'principal');let catalogue=await f.service('chamber-read',{},'','test',session);assert.deepEqual(catalogue.videos[0].pendingList.teachers.map(p=>p.id),['X:one']);await f.service('pin-submit',{operation:'podcast-ack',staffId:'X:one',pin:'123',id:video.id,version:1,acknowledged:true},'','test',session);catalogue=await f.service('chamber-read',{},'','test',session);assert.deepEqual(catalogue.videos[0].pendingList.teachers,[]);assert.ok(!JSON.stringify(catalogue).includes('acknowledgedAt'));await f.service('chamber-principal',{operation:'podcast-pending-hide',id:video.id,expectedRevision:2},'principal');assert.equal((await f.service('chamber-read',{},'','test',session)).videos[0].pendingList,undefined);});
test('explicit PIN replacement is shared by Mission login, Roll Call and Podcast across active aliases without changing other staff',async()=>{const f=fixture();f.data.cbse.facultyDraft.classes.XII.teachers.alias={name:'Synthetic Teacher',designation:'TGT',subjects:'English',teachingSections:'A',status:'active'};f.data.cbse.facultyDraft.classes.X.teachers.other={name:'Different Staff',designation:'TGT',subjects:'',teachingSections:'',status:'active'};await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');await f.service('set-pin',{staffId:'X:other',pin:'999'},'principal');const other=structuredClone(f.data.cbse.staffAccess['X:other']),old=await f.service('login',{staffId:'XII:alias',pin:'123'},'','old-mission-login');await f.service('set-pin',{staffId:'X:one',pin:'456'},'principal');assert.deepEqual(f.data.cbse.staffAccess['X:other'],other);await assert.rejects(f.service('students',{},old.customToken),/disabled or reset/);await assert.rejects(f.service('login',{staffId:'XII:alias',pin:'123'},'','new-mission-login'),/does not match|PIN/i);assert.ok((await f.service('login',{staffId:'XII:alias',pin:'456'},'','new-mission-login')).customToken);const view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken};await f.service('chamber-principal',{operation:'podcast-publish',expectedRevision:0,title:'Shared PIN guidance',youtubeUrl:'https://youtu.be/abcdefghijk',recipientIds:['X:one']},'principal');const podcast={operation:'podcast-list',staffId:'XII:alias'};await assert.rejects(f.service('pin-submit',{...podcast,pin:'123'},'','shared-pin-test',session),/PIN/);assert.equal((await f.service('pin-submit',{...podcast,pin:'456'},'','shared-pin-test',session)).videos.length,1);await f.service('pin-submit',{operation:'roll-call',staffId:'XII:alias',pin:'456',rollOperation:'report',wing:'secondary',period:'morning',reported:'no',leaveType:'today',answers:{informed:'yes',cover:'yes',exam:'yes',data:'yes'},noReason:'Emergency leave arranged and communicated.'},'','shared-pin-test',session);assert.equal(Object.values(f.data.cbse.rollCall.reports)[0].staffId,'XII:alias');});
test('missing linked profiles reuse the distributed Mission PIN and shared disable blocks every linked login',async()=>{const f=fixture();await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');const original=structuredClone(f.data.cbse.staffAccess['X:one']);f.data.cbse.facultyDraft.classes.XII.teachers.alias={name:'Synthetic Teacher',designation:'TGT',subjects:'English',teachingSections:'A',status:'active'};await f.service('generate-pins',{},'principal');assert.deepEqual(f.data.cbse.staffAccess['X:one'],original);assert.ok((await f.service('login',{staffId:'XII:alias',pin:'123'},'','linked-login')).customToken);await f.service('disable',{staffId:'X:one'},'principal');await assert.rejects(f.service('login',{staffId:'XII:alias',pin:'123'},'','linked-login'),/correct PIN/i);assert.equal(f.data.cbse.staffAccess['XII:alias'].enabled,false);});

test('advance leave saves with existing PIN, sanitizes read data, and requires Principal for No-answer review',async()=>{
 const f=fixture();await f.service('set-pin',{staffId:'X:one',pin:'123'},'principal');const access=structuredClone(f.data.cbse.staffAccess),view=await f.service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken};const answers={advance_approval:'no',advance_cover:'yes',advance_exam:'yes',advance_tasks:'yes'},save={operation:'roll-call',rollOperation:'advance-leave-save',staffId:'X:one',pin:'123',wing:'secondary',formVersion:1,dates:['1970-01-02','1970-01-04'],answers,reason:'Approval is requested for an urgent personal matter.'};
 await assert.rejects(f.service('pin-submit',{...save,pin:'999'},'','advance-test',session),/PIN/);const result=await f.service('pin-submit',save,'','advance-test',session),id=Object.keys(result.rollCall.advanceLeaves)[0];assert.equal(result.rollCall.advanceLeaves[id].status,'pending');const read=await f.service('roll-call-read',{},'','test',session);assert.equal(read.rollCall.advanceLeaves[id].answers,undefined);assert.equal(read.rollCall.advanceLeaves[id].reason,undefined);await assert.rejects(f.service('pin-submit',{operation:'roll-call',rollOperation:'advance-leave-approve',staffId:'X:one',pin:'123',leaveId:id,expectedRevision:1},'','advance-test',session),/Principal/);await f.service('roll-call-principal',{rollOperation:'advance-leave-approve',leaveId:id,expectedRevision:1},'principal');assert.equal(f.data.cbse.rollCall.advanceLeaves[id].status,'recorded');const admin=await f.service('roll-call-principal',{rollOperation:'read'},'principal');assert.equal(admin.rollCall.advanceLeaves[id].answers.advance_approval,'no');assert.deepEqual(f.data.cbse.staffAccess,access);
});

test('exam-centre attendance requires staff viewing access/PIN or Principal and exposes only the selected paper roster',async()=>{
 const f=fixture(),{schoolBoardDateSheet}=await import('../cbse-board-datesheet-model.js');let clock=Date.parse('2027-02-26T04:00:00Z');const service=createStaffService({db:f.db,auth:f.auth,now:()=>clock,displayKey:Buffer.alloc(32,7),viewSecret});f.data.cbse.mission.students['X:a:one']={guardian:'Synthetic Parent',phones:'9876543210',location:'Saved address',privateNote:'PRIVATE_DETAIL'};await service('set-pin',{staffId:'X:one',pin:'123'},'principal');const credentials=structuredClone(f.data.cbse.staffAccess),view=await service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken},row=schoolBoardDateSheet(f.data.cbse.draft,'X').rows.find(r=>r.codes.includes('184')),scope={exam:'cbse',classId:'X',paperId:row.id};await assert.rejects(service('exam-attendance-read',scope),/viewing password/);const value=await service('exam-attendance-read',scope,'','test',session);assert.deepEqual(value.students.map(p=>p.key),['X:a:one']);assert.ok(!JSON.stringify(value).includes('private-phone'));assert.ok(!JSON.stringify(value).includes('PRIVATE_DETAIL'));
 const input={...scope,operation:'exam-attendance-save',staffId:'X:one',pin:'123',studentKey:'X:a:one',status:'reported',expectedRevision:0,requestId:'centre_test_one'};await assert.rejects(service('pin-submit',{...input,pin:'999'},'','exam-test',session),/PIN/);await assert.rejects(service('pin-submit',{...input,studentKey:'X:b:two'},'','exam-test',session),/not enrolled/);const saved=await service('pin-submit',input,'','exam-test',session);assert.equal(saved.records['X:a:one'].status,'reported');assert.equal(saved.records['X:a:one'].updatedBy,'X:one');clock+=86400000;const correction={...input,status:'not-reported',expectedRevision:1,requestId:'centre_test_two'};await assert.rejects(service('pin-submit',correction,'','exam-test',session),/scheduled exam date/);await assert.rejects(service('exam-attendance-principal',correction,'outsider'),/Principal/);await service('exam-attendance-principal',{...correction,reason:'Verified against the examination centre arrival register.'},'principal');assert.deepEqual(f.data.cbse.staffAccess,credentials);
});

test('Principal contact save uses authenticated server transaction, revision conflict and private audit',async()=>{const {service,data}=fixture(),input={studentKey:'X:a:one',expectedRevision:0,contact:{numbers:{mother:{label:'Mother',phone:'9770000001'}}}},before=structuredClone(data);await assert.rejects(service('contact-principal',input,'outsider'),/Principal/);assert.deepEqual(data,before);const result=await service('contact-principal',input,'principal');assert.equal(result.ok,true);assert.equal(result.contact.updatedBy,'principal');assert.equal(result.contact.revision,1);assert.equal(result.contact.numbers.mother.phone,'9770000001');assert.ok(Object.values(data.cbse.mission.contactAudit).some(a=>a.changedBy==='principal'&&a.targetId==='X:a:one'));const saved=structuredClone(data);await assert.rejects(service('contact-principal',input,'principal'),/changed/);assert.deepEqual(data,saved);await assert.rejects(service('contact-principal',{...input,studentKey:'X:a:missing'},'principal'),/not found/);await assert.rejects(service('contact-principal',{...input,expectedRevision:1,contact:{meetingLink:'bad'}},'principal'),/permitted/);assert.deepEqual(data,saved);});

test('Roll Call reads verify access without reading unrelated revision counters',async()=>{const f=fixture(),view=await f.service('view-login',{password:'synthetic-curtain'}),paths=[],db={ref:path=>{paths.push(path);return f.db.ref(path);}},service=createStaffService({db,auth:f.auth,now:()=>1000000,displayKey:Buffer.alloc(32,7),viewSecret});await assert.rejects(service('roll-call-read',{}),/viewing password/);const value=await service('roll-call-read',{},'','test',{viewerToken:view.viewerToken});assert.equal(value.ok,true);assert.ok(paths.includes('cbse/rollCall'));for(const path of ['cbse/draft/revision','cbse/facultyDraft/revision','cbse/mission/revision'])assert.ok(!paths.includes(path),path);});
test('attendance list saves one authorized batch atomically with one PIN',async()=>{const f=fixture();f.data.cbse.draft.classes.X.sections.a.students.two={name:'Second Synthetic Student',subjects:{english:true}};const service=createStaffService({db:f.db,auth:f.auth,now:()=>Date.parse('2027-02-26T04:00:00Z'),displayKey:Buffer.alloc(32,7),viewSecret});await service('set-pin',{staffId:'X:one',pin:'123'},'principal');const view=await service('view-login',{password:'synthetic-curtain'}),session={viewerToken:view.viewerToken},input={exam:'cbse',classId:'X',paperId:'X|2027-02-26|184',operation:'exam-attendance-save',staffId:'X:one',pin:'123',changes:[{studentKey:'X:a:one',status:'reported',expectedRevision:0,requestId:'batch_endpoint_one'},{studentKey:'X:a:two',status:'not-reported',expectedRevision:0,requestId:'batch_endpoint_two'}]};await assert.rejects(service('pin-submit',{...input,pin:'999'},'','batch',session),/PIN/);await assert.rejects(service('pin-submit',{...input,changes:[input.changes[0],{...input.changes[1],studentKey:'X:b:two'}]},'','batch',session),/not enrolled/);assert.equal(f.data.cbse.examCentreAttendance,undefined);const result=await service('pin-submit',input,'','batch',session);assert.equal(result.records['X:a:one'].status,'reported');assert.equal(result.records['X:a:two'].status,'not-reported');const visible=await service('exam-attendance-read',{...input,attendanceOnly:true,revision:0},'','another-viewer',session);assert.equal(visible.records['X:a:one'].status,'reported');assert.equal(visible.records['X:a:two'].status,'not-reported');assert.equal(visible.students,undefined);const unchanged=await service('exam-attendance-read',{...input,attendanceOnly:true,revision:visible.revision},'','another-viewer',session);assert.equal(unchanged.unchanged,true);assert.equal(unchanged.records,undefined);});

test('published VEMS Preboard attendance is read-only, scoped and hides PINs and raw feed',async()=>{const f=fixture(),clock=Date.parse('2026-11-12T04:00:00Z'),feed={schemaVersion:1,session:'2026-27',examTitle:'Preboard-1',date:'2026-11-12',rows:[{classId:'X',section:'A',roll:'001',subject:'ENGLISH',status:'present',submittedAt:'2026-11-12T04:00:00Z',submittedBy:'Room Invigilator',pin:'DO_NOT_SEND'}]},service=createStaffService({db:f.db,auth:f.auth,now:()=>clock,displayKey:Buffer.alloc(32,7),viewSecret,readVemsAttendance:async()=>feed}),input={exam:'preboard1',classId:'X',paperId:'preboard1|X|184'};const value=await service('exam-attendance-read',input,'principal');assert.equal(value.records['X:a:one'].status,'reported');assert.equal(value.vems.available,true);assert.ok(!JSON.stringify(value).includes('DO_NOT_SEND'));assert.equal(value.students.length,1);const unchanged=await service('exam-attendance-read',{...input,attendanceOnly:true,revision:value.revision},'principal');assert.equal(unchanged.unchanged,true);await assert.rejects(service('exam-attendance-principal',{...input,status:'not-reported'},'principal'),/recorded in VEMS/);assert.equal(f.data.cbse.examCentreAttendance,undefined);});

test('Principal normal and linked CSV imports verify selected teacher PIN on every attempt',async()=>{const {service,data}=fixture();await service('set-pin',{staffId:'X:one',pin:'123'},'principal');const base={classId:'X',subjectId:'english',operation:'mcq-import-csv',verified:true,creditContributorId:'X:one',csvText:'Subject,Topic,Question,CorrectAnswer\nEnglish,Grammar,Normal question,A',requestId:'pin_normal_import'};await assert.rejects(service('mcq-principal',base,'principal'),/teacher.*PIN/);await assert.rejects(service('mcq-principal',{...base,creditPIN:'999'},'principal'),/PIN does not match/);assert.equal(data.cbse.mcq,undefined);const normal=await service('mcq-principal',{...base,creditPIN:'123'},'principal');assert.equal(data.cbse.mcq.questions[normal.questionIds[0]].contributorId,'X:one');assert.equal(data.cbse.mcq.questions[normal.questionIds[0]].uploadedBy,'principal');const linked={...base,linkedSet:true,csvText:'Subject,Topic,SharedPassage,Question,CorrectAnswer\nEnglish,Grammar,A shared passage,Linked first question,A\nEnglish,Grammar,,Linked second question,B',requestId:'pin_linked_import'};await assert.rejects(service('mcq-principal',linked,'principal'),/teacher.*PIN/);const saved=await service('mcq-principal',{...linked,creditPIN:'123'},'principal');assert.equal(saved.addedCount,2);const questions=saved.questionIds.map(id=>data.cbse.mcq.questions[id]);assert.ok(questions.every(q=>q.linkedSetId&&q.contributorId==='X:one'&&q.uploadedBy==='principal'));assert.equal(new Set(questions.map(q=>q.linkedSetId)).size,1);assert.ok(!JSON.stringify(data.cbse.mcq).includes('creditPIN'));await assert.rejects(service('mcq-principal',{...linked,creditPIN:'999'},'principal'),/PIN does not match/);await service('disable',{staffId:'X:one'},'principal');await assert.rejects(service('mcq-principal',{...base,creditPIN:'123',requestId:'disabled_csv_pin'},'principal'),/active personal PIN/);});
